def save():
    for name,data in [('claims',claims),('problems',problems)]:
        (P/(name+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    for name,rows,fields in [('readings',readings,['cote','scan','line','reading','alternative','evidence','weight','confidence']),('links',links,['kind','from','to','what','evidence','note_ids']),('check_events',events,['statement_id','date','who','type','outcome'])]:
        with (P/(name+'.tsv')).open('w') as f:
            w=csv.DictWriter(f,fieldnames=fields,delimiter='\t');w.writeheader();w.writerows(rows)
    (P/'items.json').write_text('[]\n')
    print(json.dumps({'claims':len(claims),'problems':len(problems),'readings':len(readings),'links':len(links),'events':len(events)}))

if __name__=='__main__':save()
